import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Dhf_H6O0.js";const n="/mbit-mcpo-proxy-download/guide/images/catalog-page.png",p=JSON.parse('{"title":"Browsing the Catalog","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/browsing.md","filePath":"catalog/browsing.md"}'),l={name:"catalog/browsing.md"};function i(s,e,d,c,h,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="browsing-the-catalog" tabindex="-1">Browsing the Catalog <a class="header-anchor" href="#browsing-the-catalog" aria-label="Permalink to &quot;Browsing the Catalog&quot;">​</a></h1><p>The Catalog is a collection of pre-configured MCP servers that you can add with a single click. Instead of manually entering URLs, commands, and auth settings, the catalog fills everything in for you.</p><h2 id="opening-the-catalog" tabindex="-1">Opening the catalog <a class="header-anchor" href="#opening-the-catalog" aria-label="Permalink to &quot;Opening the catalog&quot;">​</a></h2><p>Click <strong>Catalog</strong> in the sidebar.</p><p><img src="'+n+'" alt="Catalog page showing available servers"></p><h2 id="available-entries" tabindex="-1">Available entries <a class="header-anchor" href="#available-entries" aria-label="Permalink to &quot;Available entries&quot;">​</a></h2><p>Each catalog entry shows:</p><ul><li><strong>Name</strong> — the server name (e.g., &quot;Telekom Telecontext&quot;)</li><li><strong>Publisher</strong> — who provides this server</li><li><strong>Tags</strong> — like <code>ENTERPRISE</code>, <code>COMMUNITY</code>, <code>Multi-tool</code>, <code>Local RAG</code></li><li><strong>Description</strong> — what the server does and any requirements</li></ul><h3 id="currently-available" tabindex="-1">Currently available <a class="header-anchor" href="#currently-available" aria-label="Permalink to &quot;Currently available&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Entry</th><th>Type</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Telekom Telecontext</strong></td><td>streamable-http + OAuth</td><td>Enterprise MCP for Jira, GitLab, Confluence, and more. Requires Telekom Teleconsole authorization.</td></tr><tr><td><strong>MCP Local RAG</strong></td><td>stdio</td><td>Private document search over your PDFs, Markdown, DOCX, and HTML files. Runs entirely on your machine.</td></tr></tbody></table><h2 id="adding-a-server-from-the-catalog" tabindex="-1">Adding a server from the catalog <a class="header-anchor" href="#adding-a-server-from-the-catalog" aria-label="Permalink to &quot;Adding a server from the catalog&quot;">​</a></h2><ol><li>Find the entry you want.</li><li>Click the <strong>+</strong> button on its card.</li><li>Depending on the entry type, you may see: <ul><li>A <strong>configurator</strong> (Telecontext) where you choose categories and tools.</li><li>A <strong>folder picker</strong> (Local RAG) where you select the document folder.</li><li>A <strong>credentials dialog</strong> if the server needs API keys or environment variables.</li></ul></li><li>Click <strong>Add server</strong> (or <strong>Save</strong>).</li><li>The server appears in your <strong>Servers</strong> list, already configured and enabled.</li><li>Go to Home → <strong>Apply &amp; Restart</strong> (or <strong>Start</strong> if the gateway isn&#39;t running yet).</li></ol><div class="tip custom-block"><p class="custom-block-title">Already added?</p><p>If a catalog entry is already in your Servers list, its card shows a checkmark instead of the + button.</p></div><h2 id="searching" tabindex="-1">Searching <a class="header-anchor" href="#searching" aria-label="Permalink to &quot;Searching&quot;">​</a></h2><p>Use the <strong>search bar</strong> at the top to filter catalog entries by name or description.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./telecontext.html">Set up Telecontext</a> — detailed step-by-step guide with OAuth</li><li><a href="./local-rag.html">Set up Local RAG</a> — search your own documents</li></ul>',17)])])}const m=t(l,[["render",i]]);export{p as __pageData,m as default};
